<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Models\Sale; use App\Services\Sales\SaleService; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class SaleController extends Controller {
 public function index(Request $r){$q=Sale::where('company_id',$r->user()->company_id)->with('client');if($r->filled('search'))$q->where('sale_number','like','%'.$r->search.'%');return $q->latest('sale_date')->paginate($r->integer('per_page',20));}
 public function show(Request $r,Sale $sale){abort_unless($sale->company_id===$r->user()->company_id,404);return $sale->load('client','items.product','invoice');}
 public function store(Request $r,SaleService $service){$data=$r->validate(['branch_id'=>['nullable','exists:branches,id',function($attribute,$value,$fail)use($r){if($value && !\App\Models\Branch::where('company_id',$r->user()->company_id)->whereKey($value)->exists())$fail('The selected branch is invalid.');}],'client_id'=>['nullable','exists:clients,id',function($attribute,$value,$fail)use($r){if($value && !\App\Models\Client::where('company_id',$r->user()->company_id)->whereKey($value)->exists())$fail('The selected client is invalid.');}],'sale_date'=>'nullable|date','payment_status'=>'nullable|in:paid,credit','discount'=>'nullable|numeric|min:0','payment_method'=>'nullable|in:cash,bank,mpesa,airtel_money,tigopesa,halopesa,card,cheque,other','payment_reference'=>'nullable|string|max:100','notes'=>'nullable|string','items'=>'required|array|min:1','items.*.product_id'=>'required|exists:products,id','items.*.quantity'=>'required|numeric|min:0.001','items.*.unit_price'=>'required|numeric|min:0','items.*.discount'=>'nullable|numeric|min:0']);return response()->json($service->create($data,$r->user()),201);}
 public function destroy(Request $r,Sale $sale){abort_unless($sale->company_id===$r->user()->company_id,404);if($sale->status==='cancelled')return response()->noContent();DB::transaction(function()use($sale,$r){$sale->load('items.product','invoice.allocations');$invoice=$sale->invoice;if($invoice && $invoice->allocations()->exists()){abort(422,'This sale has a payment allocated to its invoice. Reverse the payment first, then void the sale.');}foreach($sale->items as $item){if($item->product?->track_stock){$item->product->increment('stock_quantity',$item->quantity);$item->product->refresh();$item->product->stockMovements()->create(['company_id'=>$sale->company_id,'branch_id'=>$sale->branch_id,'user_id'=>$r->user()->id,'type'=>'sale_return','quantity'=>$item->quantity,'balance_after'=>$item->product->stock_quantity,'reference_type'=>'sale','reference_id'=>$sale->id,'notes'=>'Void '.$sale->sale_number]);}}if($invoice && $invoice->status!=='cancelled'){$invoice->update(['status'=>'cancelled','amount_paid'=>0,'balance'=>0]);}$sale->update(['status'=>'cancelled','payment_status'=>'credit']);});return response()->noContent();}
}
